def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]

    # If opponent is overwhelmingly defecting, just defect.
    if n >= 5:
        opp_def = sum(1 for a in opp if a == 'D')
        if opp_def > n * 0.8:
            return 'D'

    # Check if we have already detected non-retaliation: we defected, opponent cooperated, and then cooperated again.
    for i in range(n - 1):
        if my[i] == 'D' and opp[i] == 'C' and opp[i + 1] == 'C':
            return 'D'

    last_my, last_opp = history[-1]

    if last_opp == 'D':
        if last_my == 'D':
            # Count consecutive DD at the end.
            dd = 0
            for i in range(n - 1, -1, -1):
                if my[i] == 'D' and opp[i] == 'D':
                    dd += 1
                else:
                    break
            if dd >= 3:
                return 'C'
            return 'D'
        else:
            recent = opp[-5:] if n >= 5 else opp
            recent_def = sum(1 for a in recent if a == 'D')
            if recent_def >= 3:
                return 'D'
            return 'C'
    else:
        if last_my == 'D':
            return 'C'
        else:
            # Both cooperated. Probe occasionally.
            if n > 10 and n % 20 == 0:
                return 'D'
            return 'C'
